data = JSON.parse(File.read(CATALOG_PATH))
strings = data.fetch("strings")
missing_keys = strings.each_with_object([]) do |(key, entry), keys|
  next unless key.match?(/[A-Za-z]/)

  missing = LANGUAGES.any? do |language|
    value = entry.dig("localizations", language, "stringUnit", "value")
    value.nil? || value.strip.empty?
  end
  keys << key if missing
end

if missing_keys.empty?
  puts "No missing catalog translations."
  exit 0
end

raise "Translation table has #{TRANSLATIONS.length} rows; catalog has #{missing_keys.length} missing keys" unless TRANSLATIONS.length == missing_keys.length

missing_keys.each_with_index do |key, index|
  entry = strings.fetch(key)
  LANGUAGES.each_with_index do |language, language_index|
    next if entry.dig("localizations", language, "stringUnit", "value").to_s.strip != ""

    value = TRANSLATIONS.fetch(index).fetch(language_index)
    raise "Empty translation for #{key.inspect} (#{language})" if value.strip.empty?

    entry["localizations"] ||= {}
    entry["localizations"][language] = {
      "stringUnit" => {
        "state" => "translated",
        "value" => value
      }
    }
  end
end

File.write(CATALOG_PATH, JSON.pretty_generate(data) + "\n")
puts "Filled #{missing_keys.length} catalog keys across #{LANGUAGES.length} languages."
